%% POPSTAR Experiment - 22/04/2025% 2 sessions: RL vs Trough; RL vs Random% Experiment breakdown: hotspot/MT, RL training, testing block%% Initial Settingsclc; clearcd C:\Users\bnp-admin\Desktop\Projects\POPSTAR2025b%addpath('Z:\Projects\2024-09 HOUGLANDPHD\POPSTAR')formatSpec = '%03.0f';subj_id = input('Please input subject ID: ');session.number = input('Please input session number: ');session.protocol = input('Please input session protocol (trough OR random): ');TSportID = 1; % left M1 stimulator portIDsave_flag = 1;record = []; % initiate array to store datarecord.emg = [];sc=[]; %pool all properties we can't put into bd here% sc.iti = [0.75 1.25]; % [4 6]: ITI limits (s)  % inter trial intervalsc.iti = [1 2]; % [4 6]: ITI limits (s)  % inter trial interval, 1-2 setting demos 2-3 seconds in practice as jitter, code runing delay, boss delay make it round 2-3 seconds sc.samplingFrequency = 1000; % 5000 sampling frequency (Hz)sc.emgTimeWindow = [-100 100]; % [-100 100] time window of the EMG trial (ms)sc.mepTimeWindow = [18 55]; % [18 55] time window for MEP detection (ms)sc.baselineTimeWindow = [-100 0]; % [-100 0] time window for baseline analysis (ms)sc.baselineThreshold = 15; % 15 threshold absolute EMG amplitude (µV) in the baseline time windowwarning('applyBaselineThreshold is not being used')sc.applyBaselineThreshold = 1; % 1 remeasure trials that have bad baseline (0 = do not apply this threshold)sc.emgTimeAxis = createTimeAxis(sc.emgTimeWindow,sc.samplingFrequency); % time axis for EMG data (ms)sc.mep_channel = 1; %<--- SET%% Make Directory for Subjectif ~exist(['Z:\Experimental Data\2025-04 POPSTAR\POPSTAR_' num2str(subj_id, formatSpec)], 'dir')     mkdir(['Z:\Experimental Data\2025-04 POPSTAR\POPSTAR_' num2str(subj_id, formatSpec) '\'])endif ~exist(['Z:\Experimental Data\2025-04 POPSTAR\POPSTAR_' num2str(subj_id, formatSpec) '\' session.protocol], 'dir')     mkdir(['Z:\Experimental Data\2025-04 POPSTAR\POPSTAR_' num2str(subj_id, formatSpec) '\' session.protocol])endfolderpath = ['Z:\Experimental Data\2025-04 POPSTAR\POPSTAR_' num2str(subj_id, formatSpec) '\' session.protocol '\']; %% Test Stimulator Connectiondelete(serialportfind) % use this commmand in beginningif (~exist('stimulators', 'var') || isempty('stimulators'))    try        stimulators = [];        %stimulators.left = magventure('COM3');        stimulators.left = magventure('COM3');drawnow; pause(2); drawnow;        stimulators.left.connect();        catch        fprintf(2, 'Problem with the MAGIC toolbox, please restart Matlab.\n');    endend%% Check Stimulator Connection Status -- left M1stimulators.left.armpause(3)stimulators.left.disarm%% Initialize bossbd = bossdevice;bd.initializebd.num_eeg_channels = 64;bd.num_aux_channels = 1;%set up spatial filter to detect the mu-rythmspf = zeros(64, 1);% [C3 FC1 CP1 FC5 CP5] (C3 Hjorth filter)%spf([5 21 23 25 27], 1) = [1 -0.25 -0.25 -0.25 -0.25]; % left M1spf([5], 1) = [1]; % left M1bd.spatial_filter_weights = spf;bd.alpha.offset_samples = 2; %depends on loop delay, they have demo script for this, I keep 6 from Gaborbd.alpha.amplitude_min(1) = 0;bd.alpha.amplitude_max(1) = 1e6;bd.theta.ignorebd.beta.ignore%bd.armed = 'no';bd.min_inter_trig_interval = 1.5;phase_tolerance = pi/40;bd.alpha.phase_plusminus(1) = phase_tolerance;%bd.sample_and_hold_period = 0.1;%% Hotspot / Motor ThresholdRoughMSO = input('Please input initial intensity: ');                                                            portID = TSportID; runningtrial = gethotspotbi(stimulators, portID, RoughMSO);% for MT, use MTAT PEST (purple brain icon) %% Save Motor Threshold and Stimulation ParametersMT = input('Please input subject MT: ');M1_amplitude = round(MT * 1.1); % 110% of MT%% Training RL%% RL Environment Preparation addpath('BOSS_ML');record.subjectID = subj_id;record.session = session;env = SelectPhaseBossEnv_2025(bd,stimulators.left,sc,record,save_flag, session);actionDef = getActionInfo(env);observationDef = getObservationInfo(env);%% RL Agent PreparationcriticNW = [    sequenceInputLayer(observationDef.Dimension(1), 'Normalization', 'none', 'Name', 'state')    fullyConnectedLayer(12, 'Name', 'CriticStateFC1')    leakyReluLayer(0.3, 'Name','Critic Leaky Relu1')    fullyConnectedLayer(8, 'Name', 'CriticStateFC2')    leakyReluLayer(0.3, 'Name','Critic Leaky Relu2')    lstmLayer(10,'OutputMode','sequence','Name','CriticLSTM'); % previously: 10 units    fullyConnectedLayer(8,'Name','Critic FC3')    leakyReluLayer(0.3, 'Name','Critic Leaky Relu3')    fullyConnectedLayer(numel(actionDef.Elements),'Name','output')    ];criticOptions = rlRepresentationOptions('LearnRate', 1e-3, ...    'GradientThreshold', 1, 'UseDevice', 'cpu');critic = rlQValueRepresentation(criticNW, observationDef, actionDef, ...                                'Observation', 'state', criticOptions);agentOptions = rlDQNAgentOptions(...    'UseDoubleDQN',false, ...    'TargetSmoothFactor',5e-3, ...    'ExperienceBufferLength',50, ...%50    'MiniBatchSize',15 , ... %32    'ResetExperienceBufferBeforeTraining', false, ...    'SequenceLength',2); % <- this is required!agentOptions.EpsilonGreedyExploration.EpsilonDecay = 0.005;rlDQNAgentOptions('DiscountFactor',1.0)agent = rlDQNAgent(critic, agentOptions);%% Agent Training OptionstrainOpts = rlTrainingOptions;trainOpts.MaxEpisodes = 20; %20trainOpts.MaxStepsPerEpisode = 40;trainOpts.StopTrainingCriteria = "EpisodeCount";trainOpts.StopTrainingValue = 20; trainOpts.ScoreAveragingWindowLength = 1;trainOpts.Verbose = false;trainOpts.Plots = "training-progress";trainOpts.ParallelizationOptions.Mode = "async";env.setNumStepsPerEp(trainOpts.MaxStepsPerEpisode);%% Start Training% profile on% Ready stimulators3stimulators.left.arm;stimulators.left.setAmplitude(M1_amplitude);% Loading the agent and starting the trainingagent_name = [folderpath,'dqn_agent_', num2str(subj_id, formatSpec),'_', num2str(session.number),'.mat']if exist(agent_name,'file')    fprintf('loading agent')    load(agent_name,'agent')    end% Initialize reward trackingtrainStats.RewardPerEpisode = zeros(trainOpts.MaxEpisodes, 1);for ep = 1:trainOpts.MaxEpisodes    obs = reset(env);  % Triggers env.saveMEP internally    totalReward = 0;    for step = 1:trainOpts.MaxStepsPerEpisode        % Choose action        action = getAction(agent, obs);%% Start Training% profile on% Ready stimulators3stimulators.left.arm;stimulators.left.setAmplitude(M1_amplitude);% Loading the agent and starting the trainingagent_name = [folderpath,'dqn_agent_', num2str(subj_id, formatSpec),'_', num2str(session.number),'.mat']if exist(agent_name,'file')    fprintf('loading agent')    load(agent_name,'agent')    end% Initialize reward trackingtrainStats.RewardPerEpisode = zeros(trainOpts.MaxEpisodes, 1);for ep = 1:trainOpts.MaxEpisodes    obs = reset(env);  % Triggers env.saveMEP internally    totalReward = 0;    for step = 1:trainOpts.MaxStepsPerEpisode        % Choose action        action = getAction(agent, obs);        % Step through the environment        [nextObs, reward, isDone, loggedSignals] = env.step(action);        % Create experience and train the agent        experience = rlExperience(obs, action, reward, nextObs, isDone);        agent = train(agent, experience);        % Update observation and reward        obs = nextObs;        totalReward = totalReward + reward;        if isDone            break;        end    end    % Save the agent after every episode (overwrite)    if save_flag        save(agent_name, 'agent');    end    % Store episode reward    trainStats.RewardPerEpisode(ep) = totalReward;    fprintf('Episode %d completed. Total Reward: %.2f\n', ep, totalReward);endif save_flag savedData = env.saveMEP(); savedData.record = record; save(agent_name,'agent') % Use timestamp for data file current_timestamp = datestr(now, 'yyyymmdd_HHMMSS'); Save_name_data = [folderpath, num2str(subj_id, formatSpec),'_',num2str(session.number),'_savedData_', current_timestamp, '.mat']; save(Save_name_data,'savedData')endtrainStats.agentOptions=agentOptions;% Use timestamp for training stats filecurrent_timestamp = datestr(now, 'yyyymmdd_HHMMSS');Save_name = [folderpath, num2str(subj_id, formatSpec), '_', num2str(session.number), '_trainStats_', current_timestamp, '.mat'];save(Save_name,'trainStats');        % Step through the environment        [nextObs, reward, isDone, loggedSignals] = env.step(action);        % Create experience and train the agent        experience = rlExperience(obs, action, reward, nextObs, isDone);        agent = train(agent, experience);        % Update observation and reward        obs = nextObs;        totalReward = totalReward + reward;        if isDone            break;        end    end    % Save the agent after every episode (overwrite)    if save_flag        save(agent_name, 'agent');    end    % Store episode reward    trainStats.RewardPerEpisode(ep) = totalReward;    fprintf('Episode %d completed. Total Reward: %.2f\n', ep, totalReward);endif save_flag savedData = env.saveMEP(); savedData.record = record; save(agent_name,'agent') % Use timestamp for data file current_timestamp = datestr(now, 'yyyymmdd_HHMMSS'); Save_name_data = [folderpath, num2str(subj_id, formatSpec),'_',num2str(session.number),'_savedData_', current_timestamp, '.mat']; save(Save_name_data,'savedData')endtrainStats.agentOptions=agentOptions;% Use timestamp for training 